; Graphics_SpriteDataTable_000
; Sprite graphics data table entry
; Address: $C88001
; Size: 9 bytes
;------------------------------------------------------------------------------
Graphics_SpriteDataTable_000:
	db $19, $04, $1A	 ; Sprite tile data bytes
	db $10, $07		  ; Position offset data
	db $08			   ; Sprite attributes
	db $05, $09		  ; Color/priority data
	db $0A			   ; Animation frame data

;------------------------------------------------------------------------------
; Graphics_ProcessSpriteData
; Processes sprite data with embedded data table
; Calls subroutine at $4B16 then processes sprite parameters
; Address: $C8800E
; Size: 34 bytes
;------------------------------------------------------------------------------
Graphics_ProcessSpriteData:
	JSR $4B16			; 20 16 4B | Jump to sprite processing subroutine
	; Embedded sprite data table follows
	db $21, $0D		  ; Sprite parameters
	db $18			   ; Sprite flags
	db $C4, $00		  ; Position data
	db $01, $00		  ; Tile indices
	db $05, $00		  ; Palette/priority
	db $06, $00		  ; Size parameters
	db $08			   ; Animation flags
	db $09, $00		  ; Frame data
	db $0A			   ; Control byte
	db $0D, $00, $0E	 ; Extended parameters
	db $10, $00		  ; Position offsets
	db $11, $00		  ; Additional parameters
	db $01, $00		  ; State flags
	db $C6, $6B		  ; Jump table entry
	db $01, $00		  ; Final parameters
	db $01, $02		  ; Terminator
	RTL				  ; 6B | Return from subroutine long

